func checkpointSyncMigrationState(ctx context.Context) string {
	st, ok := strategy.LoadEntireSyncState(ctx)
	if !ok {
		return checkpointSyncMigrationPending
	}
	switch st.Migration {
	case strategy.EntireSyncMigrationDone:
